mapper.select:
/*selectMasterMdCmHarmfulChemistryList*/ SELECT XX.YYYYMM ,XX.BYIT_COMORG_CODE ,XX.BUYER ,XX.BUYER_NM ,XX.AGENT ,XX.AGENT_NM ,XX.DESCRIPTION ,SUM(XX.ITEM_QTY) AS ITEM_QTY ,XX.UNIT_MEASURE ,XX.USE_MAJOR_NM ,XX.USE_MAJOR_CODE ,XX.STORE_METHOD_CODE ,XX.STORE_METHOD_NM ,XX.CAS_NO ,XX.MIN_CONTENT_RATE ,XX.MAX_CONTENT_RATE ,XX.CMC_HARMFUL_YN ,XX.PRE_TROUBLE_YN ,XX.BAN_OBJECT_YN ,XX.LIMIT_OBJECT_YN ,MAX(ADD_DATE) AS ADD_DATE FROM ( SELECT TO_CHAR(TO_DATE(A.YYYYMM,'YYYYMM'),'YYYY/MM') YYYYMM , A.BYIT_COMORG_CODE , A.BUYER ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = A.BUYER) AS BUYER_NM , A.AGENT ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = A.AGENT) AS AGENT_NM , A.BUYER_ITEM_NO , A.DESCRIPTION , A.ITEM_QTY , A.UNIT_MEASURE , (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'CM02' AND COD.CODE = A.USE_MAJOR_CODE) AS USE_MAJOR_NM , A.USE_MAJOR_CODE , A.STORE_METHOD_CODE , (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'CM04' AND COD.CODE = A.STORE_METHOD_CODE) AS STORE_METHOD_NM , A.CAS_NO , A.MIN_CONTENT_RATE , A.MAX_CONTENT_RATE , A.CMC_HARMFUL_YN , A.PRE_TROUBLE_YN , A.BAN_OBJECT_YN , A.LIMIT_OBJECT_YN , TO_CHAR(A.ADD_DATE, 'YYYY/MM/DD HH24:MI') AS ADD_DATE FROM KEP_CMC_RESULT A WHERE A.YYYYMM BETWEEN #{st_from_date} AND #{st_to_date}
AND UPPER(A.DESCRIPTION) LIKE UPPER(#{st_desc}) || '%'
AND A.BUYER = #{st_buyer_code}
AND A.AGENT = #{st_agent_code}
AND A.CAS_NO LIKE #{st_cas_no} || '%'
) XX GROUP BY XX.YYYYMM ,XX.BYIT_COMORG_CODE ,XX.BUYER ,XX.BUYER_NM ,XX.AGENT ,XX.AGENT_NM ,XX.DESCRIPTION ,XX.UNIT_MEASURE ,XX.USE_MAJOR_NM ,XX.USE_MAJOR_CODE ,XX.STORE_METHOD_CODE ,XX.STORE_METHOD_NM ,XX.CAS_NO ,XX.MIN_CONTENT_RATE ,XX.MAX_CONTENT_RATE ,XX.CMC_HARMFUL_YN ,XX.PRE_TROUBLE_YN ,XX.BAN_OBJECT_YN ,XX.LIMIT_OBJECT_YN ORDER BY XX.YYYYMM, XX.BUYER
